CREATE TABLE IF NOT EXISTS services (id SERIAL PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT NOT NULL, base_latency_ms INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS checks (id BIGSERIAL PRIMARY KEY, service_id INTEGER REFERENCES services(id), checked_at TIMESTAMPTZ NOT NULL DEFAULT now(), latency_ms INTEGER NOT NULL, ok BOOLEAN NOT NULL, status_code INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS checks_service_time ON checks(service_id, checked_at DESC); CREATE TABLE IF NOT EXISTS incidents (id BIGSERIAL PRIMARY KEY, service_id INTEGER REFERENCES services(id), severity TEXT CHECK(severity IN ('degraded','down')) NOT NULL, cause TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ, simulated BOOLEAN NOT NULL DEFAULT false); CREATE UNIQUE INDEX IF NOT EXISTS one_open_incident ON incidents(service_id) WHERE resolved_at IS NULL; INSERT INTO services(slug,name,base_latency_ms) VALUES ('frankfurter-api','Frankfurter API',500) ON CONFLICT DO NOTHING;
